// ❌ repaints on every ancestor rebuild and allocates per frame
class BadChart extends CustomPainter {
  BadChart(this.points);
  final List<Offset> points;

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()..color = Colors.blue;      // a new Paint every frame
    for (final p in points) {
      canvas.drawCircle(p, 2, paint);                // one draw call per point
    }
  }

  @override
  bool shouldRepaint(BadChart old) => true;          // the default nobody edits
}

// ✅ compares what it draws, reuses objects, batches the draws
class SparkChart extends CustomPainter {
  SparkChart({required this.points, required this.color, super.repaint});

  final List<Offset> points;
  final Color color;

  static final Paint _stroke = Paint()
    ..style = PaintingStyle.stroke
    ..strokeWidth = 2
    ..isAntiAlias = true;

  @override
  void paint(Canvas canvas, Size size) {
    final path = Path()..addPolygon(points, false);
    canvas.drawPath(path, _stroke..color = color);   // one draw for the line
  }

  @override
  bool shouldRepaint(SparkChart old) =>
      old.color != color || !listEquals(old.points, points);
}

// ✅ animate through `repaint`: the widget never rebuilds, only paint runs
RepaintBoundary(
