// ✅ cheap skeleton first, real work once the transition has settled
class _DetailsState extends State<DetailsPage> {
  Order? _order;
  bool _started = false;

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (_started) return;                       // runs again on theme changes
    _started = true;

    final animation = ModalRoute.of(context)!.animation!;  // not legal in initState
    if (animation.isCompleted) {
      _load();
      return;
    }
    void onStatus(AnimationStatus status) {
      if (status != AnimationStatus.completed) return;
      animation.removeStatusListener(onStatus);
      _load();
    }
    animation.addStatusListener(onStatus);
  }

  Future<void> _load() async {
    final order = await repository.order(widget.id);   // async, off the frame
    if (mounted) setState(() => _order = order);
  }

  @override
  Widget build(BuildContext context) => _order == null
      ? const OrderSkeleton()          // the frame the transition can afford
      : OrderView(order: _order!);
}

