        await summary.writeTimelineToFile('feed_scroll',
            pretty: true, includeSummary: true);

        final json = summary.summaryJson;
        final buildP90 = json['90th_percentile_frame_build_time_millis'] as num;
        final rasterP90 =
            json['90th_percentile_frame_rasterizer_time_millis'] as num;
        if (buildP90 > 12 || rasterP90 > 12) {
          throw Exception('p90 regressed: build ${buildP90}ms, '
              'raster ${rasterP90}ms (budget 12ms)');
        }
      },
    );

