// ✅ send bytes, decode inside, return through Isolate.exit (no copy back)
Future<List<Product>> loadProducts(Uri url) async {
  final response = await http.get(url);                    // IO, not CPU
  final payload = TransferableTypedData.fromList([response.bodyBytes]);
  return Isolate.run(() {
    final bytes = payload.materialize().asUint8List();     // moved, not copied
    final list = jsonDecode(utf8.decode(bytes)) as List;
    return [for (final e in list) Product.fromJson(e as Map<String, dynamic>)];
  });
}

// ✅ one long-lived worker when the work repeats: spawn is paid once
class ParserWorker {
  final _handshake = ReceivePort();
  final _results = ReceivePort();
  late final SendPort _toWorker;

  Stream<dynamic> get results => _results;

  Future<void> start() async {
    await Isolate.spawn(
      _entry,
      (_handshake.sendPort, _results.sendPort, RootIsolateToken.instance!),
    );
    _toWorker = await _handshake.first as SendPort;
  }

  void parse(String json) => _toWorker.send(json);

  static void _entry((SendPort, SendPort, RootIsolateToken) args) {
    final (handshake, results, token) = args;
    // plugins are unreachable from a background isolate without this
    BackgroundIsolateBinaryMessenger.ensureInitialized(token);
    final inbox = ReceivePort();
    handshake.send(inbox.sendPort);
    inbox.listen((message) => results.send(_parse(message as String)));
  }
}

