class _Bars extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    for (final v in values) {
      canvas.drawRect(rectFor(v), Paint()..color = Colors.teal);  // per bar
    }
  }
}

// ✅ hoist what never changes, reuse the buffer that does
class _ChartState extends State<Chart> {
  static final Paint _fill = Paint()..color = Colors.teal;     // once
  late final Float32List _scaled = Float32List(widget.data.length);
  late final String _label = '${widget.data.length} points';   // once
  late final VoidCallback _onTap = () => _select(widget.data); // once

  @override
  Widget build(BuildContext context) => CustomPaint(
        painter: _Bars(_scaled, _fill, _label, _onTap, repaint: _controller),
        child: const _Legend(),        // const: canonicalised, never allocated
      );
}

// ✅ the per-frame work writes into the buffer instead of building a new one
void _scale(double t) {
  for (var i = 0; i < widget.data.length; i++) {
    _scaled[i] = widget.data[i].value * t;
  }
}

