// ✅ a ui.Image is a small Dart handle over a large native buffer
Future<void> exportCard(GlobalKey key) async {
  final boundary =
      key.currentContext!.findRenderObject()! as RenderRepaintBoundary;
  final image = await boundary.toImage(pixelRatio: 2);
  try {
    final data = await image.toByteData(format: ui.ImageByteFormat.png);
    await save(data!.buffer.asUint8List());
  } finally {
    image.dispose();          // without this the bitmap stays in native memory
  }
}

